entry.content:
前言
记录一手程序设计的实验作业，所使用的算法都是一些普通的算法，时间原因来不及做出太好的，只是稍微对几点想法说一下
函数体系及实现
核心是我们的头文件
#ifndef WLC_BN_H#define WLC_BN_H#include "wlc_types.h"#include &lt;stdlib.h&gt;#include &lt;stdio.h&gt;#include &lt;time.h&gt;#ifdef __cplusplusextern "C" {#endif#ifndef MAX_BN_DIGS#define MAX_BN_DIGS 1024#endif#ifndef dig_t#if WBITS == 64typedef uint64_t dig_t;#elsetypedef uint32_t dig_t;					// 这个程序中WBITS是32#endif#endif#define DIG_BYTES (WBITS / 8)#define DIG_MASK ((1ULL &lt;&lt; WBITS) - 1)	// 掩码 0xFFFFFFFF// 返回值（错误码）定义typedef enum {    BN_SUCCESS = 0,    BN_ERR_NULL_PTR = -1,    BN_ERR_INVALID_SIZE = -2,    BN_ERR_BUFFER_OVERFLOW = -3,    BN_ERR_MEMORY = -4,    BN_ERR_MODULUS_EVEN = -5,    BN_ERR_INVALID_PARAM = -6,    BN_ERR_NO_MODULAR_INVERSE = -7,    BN_ERR_MONTGOMERY_INVALID = -8,    BN_ERR_NO_INVERSE = -9,    BN_ERR_ALL_NEGATIVE_RESULT = -10,    BN_ERR_FIRST_NEGATIVE_RESULT = -11,    BN_ERR_SECOND_NEGATIVE_RESULT = -12,    BN_ERR_RANDOM_ALLOC_FAIL = -13,} bn_err_t;// Resize函数能否截断有用数据typedef enum {    BN_RESIZE_SAFE,       BN_RESIZE_TRUNCATE} bn_resize_mode_t;    // BN结构体，封装大整数typedef struct {    dig_t *data;      // 数据数组    int used_digs;    // 实际使用的dig_t个数，方便我们判断数的大小    int capacity;     // 容量（dig_t个数），方便我们判断内存大小是否满足需要} bn_t;// 蒙哥马利上下文结构体typedef struct {    bn_t N;           // 模数    bn_t R;           // R = 2^k    bn_t N_prime;     // N' = -N⁻¹ mod R    bn_t R2;          // R2 = R^2 mod N     int k;            // R的位数    int k_digs;       // k对应的dig_t数量} mont_ctx_t;// ==================== 内存管理 ====================bn_err_t bn_init(bn_t *bn, int capacity);bn_err_t bn_init_copy(bn_t *bn, const dig_t *data, int digs);bn_err_t bn_free(bn_t *bn);bn_err_t bn_resize(bn_t *bn, int new_capacity, bn_resize_mode_t mode);bn_err_t bn_ensure_capacity(bn_t *bn, int required_digs);// ==================== 工具函数 ====================int bn_get_bits(const bn_t *bn);int bn_cmp(const bn_t *a, const bn_t *b);int bn_is_zero(const bn_t *bn);int bn_is_even(const bn_t *bn);int bn_is_one(const bn_t *bn);bn_err_t bn_set_zero(bn_t *bn);bn_err_t bn_set_one(bn_t *bn);bn_err_t bn_copy(bn_t *dst, const bn_t *src);bn_err_t bn_rand(bn_t *bn, int bits);bn_err_t bn_rand_range(bn_t *bn, const bn_t *max);bn_err_t bn_rand_security(bn_t *bn, int bits);void bn_print(const bn_t *bn, const char *name);void bn_print_hex(const bn_t *bn, const char *name);bn_err_t bn_truncate_replace(bn_t *dst, const bn_t *src, int num_digs);bn_err_t bn_truncate(bn_t *bn, int digs);bn_err_t bn_truncate_bits(bn_t *bn, int bits);// ==================== 基础运算 ====================bn_err_t bn_add(bn_t *r, const bn_t *a, const bn_t *b);bn_err_t bn_sub(bn_t *r, const bn_t *a, const bn_t *b);bn_err_t bn_sub_signed(bn_t *r, const bn_t *a, const bn_t *b);bn_err_t bn_sub_with_sign(bn_t *r, int *is_negative, const bn_t *a, const bn_t *b);bn_err_t bn_mul(bn_t *r, const bn_t *a, const bn_t *b);bn_err_t bn_sqr(bn_t *r, const bn_t *a);bn_err_t bn_div(bn_t *q, bn_t *r, const bn_t *a, const bn_t *b);bn_err_t bn_mod(bn_t *r, const bn_t *a, const bn_t *m);bn_err_t bn_lsh(bn_t *r, const bn_t *a, int bits);bn_err_t bn_rsh(bn_t *r, const bn_t *a, int bits);dig_t bn_add_dig(bn_t *r, const bn_t *a, dig_t b);dig_t bn_sub_dig(bn_t *r, const bn_t *a, dig_t b);// ==================== 模运算 ====================bn_err_t bn_mod_add(bn_t *r, const bn_t *a, const bn_t *b, const bn_t *m);bn_err_t bn_mod_sub(bn_t *r, const bn_t *a, const bn_t *b, const bn_t *m);bn_err_t bn_mod_mul(bn_t *r, const bn_t *a, const bn_t *b, const bn_t *m);bn_err_t bn_mod_sqr(bn_t *r, const bn_t *a, const bn_t *m);bn_err_t bn_mod_exp(bn_t *r, const bn_t *a, const bn_t *e, const bn_t *m);bn_err_t bn_mod_inv(bn_t *r, const bn_t *a, const bn_t *m);bn_err_t bn_mod_hlv(bn_t *r, const bn_t *a, const bn_t *m);// ==================== 蒙哥马利算法 ====================// 蒙哥马利上下文管理bn_err_t mont_ctx_init(mont_ctx_t *ctx, const bn_t *N);void mont_ctx_free(mont_ctx_t *ctx);bn_err_t mont_ctx_compute(mont_ctx_t *ctx, const bn_t *N);// 蒙哥马利预计算bn_err_t mont_compute_R(bn_t *R, const bn_t *N, int *k);bn_err_t mont_compute_N_prime(bn_t *N_prime, const bn_t *N, const bn_t *R);// 蒙哥马利转换bn_err_t mont_map(bn_t *a_mont, const bn_t *a, const mont_ctx_t *ctx);bn_err_t mont_reduce(bn_t *a, const bn_t *a_mont, const mont_ctx_t *ctx);// 蒙哥马利运算bn_err_t mont_add(bn_t *r, const bn_t *a, const bn_t *b, const mont_ctx_t *ctx);bn_err_t mont_sub(bn_t *r, const bn_t *a, const bn_t *b, const mont_ctx_t *ctx);bn_err_t mont_mul(bn_t *r, const bn_t *a, const bn_t *b, const mont_ctx_t *ctx);bn_err_t mont_sqr(bn_t *r, const bn_t *a, const mont_ctx_t *ctx);bn_err_t mont_exp(bn_t *r, const bn_t *a, const bn_t *e, const mont_ctx_t *ctx);bn_err_t mont_redc_internal(bn_t *r, const bn_t *T, const bn_t *N, const bn_t *N_prime, int k);// 使用蒙哥马利的模运算（高级接口）bn_err_t bn_mod_mul_mont(bn_t *r, const bn_t *a, const bn_t *b, const bn_t *m);bn_err_t bn_mod_exp_mont(bn_t *r, const bn_t *a, const bn_t *e, const bn_t *m);// ==================== 辅助函数 ====================bn_err_t bn_from_hex(bn_t *bn, const char *hex_str);bn_err_t bn_from_bytes(bn_t *bn, const unsigned char *bytes, int byte_len);bn_err_t bn_to_bytes(unsigned char *bytes, int *byte_len, const bn_t *bn, int max_len);bn_err_t bn_extend(bn_t *bn, int digs, dig_t fill);#ifdef __cplusplus}#endif#endif /* WLC_BN_H */
内存管理
鉴于我们是进行大整数运算，可能会申请大量的内存，因此我设立了一系列函数帮助我在堆上管理内存
bn_err_t bn_init(bn_t *bn, int capacity);bn_err_t bn_init_copy(bn_t *bn, const dig_t *data, int digs);bn_err_t bn_free(bn_t *bn);bn_err_t bn_resize(bn_t *bn, int new_capacity);bn_err_t bn_ensure_capacity(bn_t *bn, int required_digs);
首先是
bn_err_t bn_init(bn_t *bn, int capacity);
帮助我们初始化bn_t这个结构体，得到一个至少容量为1的dig容量，并且calloc会将内存清零便于我们快速使用
bn_err_t bn_init(bn_t *bn, int capacity) {    if (!bn) return BN_ERR_NULL_PTR;    if (capacity &lt;= 0) capacity = 1;        bn-&gt;data = (dig_t *)calloc(capacity, sizeof(dig_t));    if (!bn-&gt;data) return BN_ERR_MEMORY;        bn-&gt;capacity = capacity;    bn-&gt;used_digs = 0;    return BN_SUCCESS;}
方便我们申请一个bn_t结构体进行后续使用
bn_t temp;bn_init(&amp;temp, 0);
然后是
bn_err_t bn_init_copy(bn_t *bn, const dig_t *data, int digs);
一样是初始化结构体，但是进一步实现了数的复制，并且可以通过参数设置复制的digs数
bn_err_t bn_init_copy(bn_t *bn, const dig_t *data, int digs) {    bn_err_t err = bn_init(bn, digs);    if (err != BN_SUCCESS) return err;        if (data &amp;&amp; digs &gt; 0) {        memcpy(bn-&gt;data, data, digs * sizeof(dig_t));        bn-&gt;used_digs = digs;        while (bn-&gt;used_digs &gt; 0 &amp;&amp; bn-&gt;data[bn-&gt;used_digs - 1] == 0) {		// 假如复制数据使前面的digs全是0（也称前导0），则收缩            bn-&gt;used_digs--;        }    }    return BN_SUCCESS;}
然后是内存释放函数
bn_err_t bn_free(bn_t *bn);
帮助我们释放内存
bn_err_t bn_free(bn_t *bn) {    if (bn &amp;&amp; bn-&gt;data) {        free(bn-&gt;data);        bn-&gt;data = NULL;	// 清空指针，防止UAF        bn-&gt;capacity = 0;        bn-&gt;used_digs = 0;        return BN_SUCCESS;    }    return BN_ERR_NULL_PTR;}
然后是动态内存调整
bn_err_t bn_resize(bn_t *bn, int new_capacity, bn_resize_mode_t mode);
方便我们调整capacity的大小
bn_err_t bn_resize(bn_t *bn, int new_capacity, bn_resize_mode_t mode) {    if (!bn) return BN_ERR_NULL_PTR;    if (new_capacity &lt;= 0) return BN_ERR_INVALID_SIZE;        if (new_capacity == bn-&gt;capacity) {        return BN_SUCCESS;    }        if (new_capacity &lt; bn-&gt;capacity) {        if (mode == BN_RESIZE_SAFE) {			// 不允许截断非0数据            for (int i = new_capacity; i &lt; bn-&gt;used_digs; i++) {                if (bn-&gt;data[i] != 0) {                    return BN_ERR_TRUNCATION;                }            }        }        if (bn-&gt;used_digs &gt; new_capacity) {            bn-&gt;used_digs = new_capacity;	// 缩减大小        }    }    dig_t *new_data = (dig_t *)realloc(bn-&gt;data, new_capacity * sizeof(dig_t));    if (!new_data) return BN_ERR_MEMORY;	// 失败也保存原来数据        bn-&gt;data = new_data;        // 清零新增大小的内存    if (new_capacity &gt; bn-&gt;capacity) {        memset(bn-&gt;data + bn-&gt;capacity, 0, (new_capacity - bn-&gt;capacity) * sizeof(dig_t));    }        bn-&gt;capacity = new_capacity;    return BN_SUCCESS;}
然后是capacity校验函数，防止出现内存不足的情况
bn_err_t bn_ensure_capacity(bn_t *bn, int required_digs);
这里不可能发生截断，所以使用了BN_RESIZE_TRUNCATE
bn_err_t bn_ensure_capacity(bn_t *bn, int required_digs) {    if (!bn) return BN_ERR_NULL_PTR;    if (required_digs &lt;= 0) return BN_ERR_INVALID_SIZE;        if (required_digs &lt;= bn-&gt;capacity) {        return BN_SUCCESS;    }        // 增长策略：取所需大小的1.5倍    int new_capacity = required_digs * 3 / 2 + 1;    return bn_resize(bn, new_capacity, BN_RESIZE_TRUNCATE);}
工具函数
对于大整数运算中，去判断或是设置某一特定位是1还是0便于我们操作，比如说设置一个，或者是在蒙哥马利模幂中判断是否为1，或者是得到我们的位数都需要依赖这两个函数
因此我们先设置这两个函数
static int bn_get_bit(const bn_t *bn, int bit) {    if (!bn || bit &lt; 0) return 0;    int word_idx = bit / WBITS;    int bit_idx = bit % WBITS;    if (word_idx &gt;= bn-&gt;used_digs) return 0;	// 零拓展    return (bn-&gt;data[word_idx] &gt;&gt; bit_idx) &amp; 1;	// 右移加&amp;运算}static bn_err_t bn_set_bit(bn_t *bn, int bit, int value) {    if (!bn || bit &lt; 0) return BN_ERR_NULL_PTR;    int word_idx = bit / WBITS;    int bit_idx = bit % WBITS;    if (word_idx &gt;= bn-&gt;capacity) {        bn_err_t err = bn_ensure_capacity(bn, word_idx + 1);        if(err != BN_SUCCESS){            return err;        }    }    if (word_idx &gt;= bn-&gt;used_digs) {        bn-&gt;used_digs = word_idx + 1;    }    if (value) {        bn-&gt;data[word_idx] |= (dig_t)1 &lt;&lt; bit_idx;	// 设为1    } else {        bn-&gt;data[word_idx] &amp;= ~((dig_t)1 &lt;&lt; bit_idx);	// 设为0        // 如果清除的是最高位且 word 变为 0，更新 used_digs        if (word_idx == bn-&gt;used_digs - 1 &amp;&amp; bn-&gt;data[word_idx] == 0) {            while (bn-&gt;used_digs &gt; 0 &amp;&amp; bn-&gt;data[bn-&gt;used_digs - 1] == 0) {                bn-&gt;used_digs--;            }        }    }    return BN_SUCCESS;}
然后我们设置一个用来判断数字有多少位的函数
int bn_get_bits(const bn_t *bn) {    if (!bn || bn-&gt;used_digs == 0) return 0;	// 空数据        int i = bn-&gt;used_digs - 1;    dig_t top = bn-&gt;data[i];	// 只需要取最高位的数字dig_t来判断    #if WBITS == 64    return i * WBITS + (64 - __builtin_clzll(top));#else    return i * WBITS + (32 - __builtin_clz(top));	// 这个是32位程序使用的#endif}
判断是否为0，是否为偶数（奇数）这类函数也顺便实现一下
int bn_is_zero(const bn_t *bn) {    if (!bn) return 0;    return (bn-&gt;used_digs == 0) || (bn-&gt;used_digs == 1 &amp;&amp; bn-&gt;data[0] == 0);}int bn_is_one(const bn_t *bn) {    if (!bn) return 0;    return (bn-&gt;used_digs == 1 &amp;&amp; bn-&gt;data[0] == 1);}int bn_is_even(const bn_t *bn) {    if (!bn) return 0;    if (bn-&gt;used_digs == 0) return 1;    return (bn-&gt;data[0] &amp; 1) == 0;}// 判断正确则返回1，否则返回0
比较函数对于相减和模计算比较重要
int bn_cmp(const bn_t *a, const bn_t *b) {    if (!a || !b) return 0;        if (a-&gt;used_digs != b-&gt;used_digs) {					// 先比较dig_t的数目        return a-&gt;used_digs &gt; b-&gt;used_digs ? 1 : -1;    }        for (int i = a-&gt;used_digs - 1; i &gt;= 0; i--) {        if (a-&gt;data[i] &gt; b-&gt;data[i]) return 1;			// 再从高dig_t比较到低dig_t        if (a-&gt;data[i] &lt; b-&gt;data[i]) return -1;    }    return 0;}
下面是几个比较常用的赋值函数
bn_err_t bn_set_zero(bn_t *bn) {    if (!bn) return BN_ERR_NULL_PTR;        if (bn-&gt;data) {        memset(bn-&gt;data, 0, bn-&gt;capacity * sizeof(dig_t));    }    bn-&gt;used_digs = 0;    return BN_SUCCESS;}
清零函数高效清除数据
再设置一个置1的
bn_err_t bn_set_one(bn_t *bn) {    if (!bn) return BN_ERR_NULL_PTR;        bn_err_t err = bn_ensure_capacity(bn, 1);    if (err != BN_SUCCESS) return err;        if (bn-&gt;used_digs &gt; 0) {        memset(bn-&gt;data, 0, bn-&gt;capacity * sizeof(dig_t));    }    // 设置值为1    bn-&gt;data[0] = 1;    bn-&gt;used_digs = 1;        return BN_SUCCESS;}
然后是复制操作
bn_err_t bn_copy(bn_t *dst, const bn_t *src) {    if (!dst || !src) return BN_ERR_NULL_PTR;    if (dst == src) return BN_SUCCESS;    if (src-&gt;used_digs == 0) {        return bn_set_zero(dst);	// 清零    }    bn_err_t err = bn_ensure_capacity(dst, src-&gt;used_digs);    if (err != BN_SUCCESS) return err;        memcpy(dst-&gt;data, src-&gt;data, src-&gt;used_digs * sizeof(dig_t));	// 复制    dst-&gt;used_digs = src-&gt;used_digs;        if (dst-&gt;used_digs &lt; dst-&gt;capacity) {        memset(dst-&gt;data + dst-&gt;used_digs, 0, (dst-&gt;capacity - dst-&gt;used_digs) * sizeof(dig_t));	// 清零dst高位    }        return BN_SUCCESS;}
还有随机数生成器
bn_err_t bn_rand(bn_t *bn, int bits) {    if (!bn) return BN_ERR_NULL_PTR;    if (bits &lt;= 0) return BN_ERR_INVALID_SIZE;        int digs = (bits + WBITS - 1) / WBITS;    bn_err_t err = bn_ensure_capacity(bn, digs);    if (err != BN_SUCCESS) return err;        static int seeded = 0;    if (!seeded) {        srand(time(NULL));        seeded = 1;    }        for (int i = 0; i &lt; digs; i++) {        bn-&gt;data[i] = (dig_t)rand() &lt;&lt; 17 | (dig_t)rand() &lt;&lt; 2  | (dig_t)(rand() &amp; 0x3); 	// rand返回0~0x7FFF    }        // 处理最高位，确保位数正确    int bit_mask = bits % WBITS;    if (bit_mask &gt; 0) {        dig_t mask = (1ULL &lt;&lt; bit_mask) - 1;        bn-&gt;data[digs - 1] &amp;= mask;        // 确保最高位为1        if (bit_mask &gt; 1) {            bn-&gt;data[digs - 1] |= (1ULL &lt;&lt; (bit_mask - 1));        }    }else {        if (digs &gt; 0) {            bn-&gt;data[digs - 1] |= (1ULL &lt;&lt; (WBITS - 1));        }    }        bn-&gt;used_digs = digs;    while (bn-&gt;used_digs &gt; 0 &amp;&amp; bn-&gt;data[bn-&gt;used_digs - 1] == 0) {        bn-&gt;used_digs--;    }        return BN_SUCCESS;}
rand函数生成的随机数质量不高，我们使用BCryptGenRandom来生成高质量的随机数
bn_err_t bn_rand_security(bn_t *bn, int bits) {    if (!bn) return BN_ERR_NULL_PTR;    if (bits &lt;= 0) return BN_ERR_INVALID_SIZE;        int digs = (bits + WBITS - 1) / WBITS;    bn_err_t err = bn_ensure_capacity(bn, digs);    if (err != BN_SUCCESS) return err;        size_t total_bytes = digs * sizeof(dig_t);        NTSTATUS status = BCryptGenRandom(        NULL,        (PUCHAR)bn-&gt;data,        (ULONG)total_bytes,        BCRYPT_USE_SYSTEM_PREFERRED_RNG    );        if (status != 0) {        return BN_ERR_RANDOM_ALLOC_FAIL;    }        bn_truncate_bits(bn,bits);	// 截断    int bit_mask = bits % WBITS;    int last_word = digs - 1;        if (bit_mask &gt; 0) {        // 设置最高位为1        if (bit_mask &gt; 1) {            bn-&gt;data[last_word] |= (1ULL &lt;&lt; (bit_mask - 1));        }    } else {        if (digs &gt; 0) {            bn-&gt;data[last_word] |= (1ULL &lt;&lt; (WBITS - 1));        }    }        bn-&gt;used_digs = digs;    while (bn-&gt;used_digs &gt; 0 &amp;&amp; bn-&gt;data[bn-&gt;used_digs - 1] == 0) {        bn-&gt;used_digs--;    }        return BN_SUCCESS;}
然后是打印函数
void bn_print(const bn_t *bn, const char *name) {    if (!bn) {        printf("\n%s: (null)\n", name ? name : "bn");        return;    }        printf("\n%s: ", name ? name : "bn");    if (bn_is_zero(bn)) {        printf("0\n");        return;    }    printf("0x");    for (int i = bn-&gt;used_digs - 1; i &gt;= 0; i--) {#if WBITS == 64        if (i == bn-&gt;used_digs - 1) {            printf("%" PRIx64, (uint64_t)bn-&gt;data[i]);        } else {            printf("%016" PRIx64, (uint64_t)bn-&gt;data[i]);        }#else        if (i == bn-&gt;used_digs - 1) {            printf("%" PRIx32, (uint32_t)bn-&gt;data[i]);        } else {            printf("%08" PRIx32, (uint32_t)bn-&gt;data[i]);        }#endif        printf(" ");    }    printf(" (%d digs)\n", bn-&gt;used_digs);}
AI帮我设计了一个debug的printf
void bn_print_debug(const bn_t *bn, const char *name) {    if (!bn) {        printf("%s: (null)\n", name ? name : "bn");        return;    }        printf("\n=== %s Debug Info ===\n", name ? name : "bn");        // 基本状态    printf("  used_digs: %d\n", bn-&gt;used_digs);    printf("  capacity:  %d\n", bn-&gt;capacity);        // 安全检查    if (!bn-&gt;data) {        printf("  ERROR: data pointer is NULL!\n");        return;    }    if (bn-&gt;capacity &lt;= 0) {        printf("  ERROR: invalid capacity (%d)!\n", bn-&gt;capacity);        return;    }    if (bn-&gt;used_digs &gt; bn-&gt;capacity) {        printf("  ERROR: used_digs (%d) &gt; capacity (%d)!\n",                bn-&gt;used_digs, bn-&gt;capacity);    }        // 所有分配的字    printf("  All allocated words (%d total):\n", bn-&gt;capacity);    for (int i = bn-&gt;capacity - 1; i &gt;= 0; i--) {        printf("    [%3d]: 0x", i);        #if WBITS == 64        printf("%016" PRIx64, (uint64_t)bn-&gt;data[i]);#else        printf("%08" PRIx32, (uint32_t)bn-&gt;data[i]);#endif                // 状态标记        if (i &gt;= bn-&gt;used_digs) {            printf("  [unused]");            if (bn-&gt;data[i] != 0) {                printf(" (WARNING: non-zero!)");            }        } else if (i == bn-&gt;used_digs - 1) {            printf("  [MSB]");  // Most Significant Bit            if (bn-&gt;data[i] == 0) {                printf(" (ERROR: leading zero!)");            }        } else if (bn-&gt;data[i] == 0) {            printf("  [zero]");        }                printf("\n");    }        // 标准格式（紧凑）    printf("  Compact hex: ");    if (bn-&gt;used_digs == 0 || (bn-&gt;used_digs == 1 &amp;&amp; bn-&gt;data[0] == 0)) {        printf("0");    } else {        printf("0x");        int i = bn-&gt;used_digs - 1;                // 最高位不带前导零#if WBITS == 64        printf("%" PRIx64, (uint64_t)bn-&gt;data[i]);#else        printf("%" PRIx32, (uint32_t)bn-&gt;data[i]);#endif                // 其他位带前导零        for (i--; i &gt;= 0; i--) {#if WBITS == 64            printf("%016" PRIx64, (uint64_t)bn-&gt;data[i]);#else            printf("%08" PRIx32, (uint32_t)bn-&gt;data[i]);#endif        }    }    printf("\n");        // 大小估算    size_t used_bytes = bn-&gt;used_digs * sizeof(dig_t);    size_t alloc_bytes = bn-&gt;capacity * sizeof(dig_t);    printf("  Memory: %zu/%zu bytes used (%.1f%%)\n",            used_bytes, alloc_bytes,            alloc_bytes ? (100.0 * used_bytes / alloc_bytes) : 0.0);        printf("================================\n\n");}
然后是截断函数，对于模有奇效
这种是复制型的
bn_err_t bn_truncate_copy(bn_t *dst, const bn_t *src, int digs) {    if (!dst || !src) return BN_ERR_NULL_PTR;    if (digs &lt;= 0) return BN_ERR_INVALID_PARAM;        // 确保dst有足够容量    bn_err_t err = bn_ensure_capacity(dst, digs);    if (err != BN_SUCCESS) return err;        // 清零    memset(dst-&gt;data, 0, dst-&gt;capacity * sizeof(dig_t));        // 计算实际复制数量    int copy_digs = (src-&gt;used_digs &lt; digs) ? src-&gt;used_digs : digs;        // 复制低位    memcpy(dst-&gt;data, src-&gt;data, copy_digs * sizeof(dig_t));        dst-&gt;used_digs = copy_digs;        // 去除前导零    while (dst-&gt;used_digs &gt; 0 &amp;&amp; dst-&gt;data[dst-&gt;used_digs - 1] == 0) {        dst-&gt;used_digs--;    }        return BN_SUCCESS;}
这种是对自身数据进行截断的
bn_err_t bn_truncate(bn_t *bn, int digs) {    if (!bn) return BN_ERR_NULL_PTR;    if (digs &lt; 0) return BN_ERR_INVALID_SIZE;        if (digs &lt; bn-&gt;used_digs) {        bn-&gt;used_digs = digs;    }        if (digs &lt; bn-&gt;capacity) {        memset(bn-&gt;data + digs, 0, (bn-&gt;capacity - digs) * sizeof(dig_t));    }        return BN_SUCCESS;}
还有一种是对位截断的
bn_err_t bn_truncate_bits(bn_t *bn, int bits) {    if (!bn) return BN_ERR_NULL_PTR;    if (bits &lt;= 0) return BN_ERR_INVALID_SIZE;        // 计算需要保留的字数    int digs_needed = (bits + WBITS - 1) / WBITS;    int extra_bits = bits % WBITS;    // 如果原数位数少于需要的，不需要截断    if (bn-&gt;used_digs &lt;= digs_needed) {        if (bn-&gt;used_digs == digs_needed) {		// 只需处理最高字的掩码            if (extra_bits &gt; 0) {                dig_t mask = ((dig_t)1 &lt;&lt; extra_bits) - 1;                bn-&gt;data[digs_needed - 1] &amp;= mask;            }        }        return BN_SUCCESS;    }        memset(bn-&gt;data + digs_needed, 0, (bn-&gt;used_digs - digs_needed) * sizeof(dig_t));    bn-&gt;used_digs = digs_needed;    // 处理最高字的掩码    if (extra_bits &gt; 0) {        dig_t mask = ((dig_t)1 &lt;&lt; extra_bits) - 1;        bn-&gt;data[digs_needed - 1] &amp;= mask;    }        while (bn-&gt;used_digs &gt; 0 &amp;&amp; bn-&gt;data[bn-&gt;used_digs - 1] == 0) {        bn-&gt;used_digs--;    }        return BN_SUCCESS;}
基础运算
加法就是简单的实现
bn_err_t bn_add(bn_t *r, const bn_t *a, const bn_t *b) {    if (!r || !a || !b) return BN_ERR_NULL_PTR;        // 添加原地操作支持    if (r == a || r == b) {        bn_t temp;        // 初始化时指定容量        int max_digs = MAX(a-&gt;used_digs, b-&gt;used_digs);        bn_init(&amp;temp, max_digs + 1);                bn_err_t err = bn_add(&amp;temp, a, b);        if (err != BN_SUCCESS) {            bn_free(&amp;temp);            return err;        }        err = bn_copy(r, &amp;temp);        bn_free(&amp;temp);        return err;    }    int max_digs = MAX(a-&gt;used_digs, b-&gt;used_digs);    bn_err_t err = bn_ensure_capacity(r, max_digs + 1);    if (err != BN_SUCCESS) return err;        memset(r-&gt;data, 0, r-&gt;capacity * sizeof(dig_t));        uint64_t carry = 0;    int i;    for (i = 0; i &lt; max_digs; i++) {        uint64_t a_val = (i &lt; a-&gt;used_digs) ? a-&gt;data[i] : 0;        uint64_t b_val = (i &lt; b-&gt;used_digs) ? b-&gt;data[i] : 0;        carry += a_val + b_val;        r-&gt;data[i] = (dig_t)(carry &amp; DIG_MASK);        carry &gt;&gt;= WBITS;    }        if (carry &gt; 0) {        r-&gt;data[i] = (dig_t)carry;        r-&gt;used_digs = max_digs + 1;    } else {        r-&gt;used_digs = max_digs;    }        while (r-&gt;used_digs &gt; 0 &amp;&amp; r-&gt;data[r-&gt;used_digs - 1] == 0) {        r-&gt;used_digs--;    }        return BN_SUCCESS;}
还有减法（a&gt;b）
bn_err_t bn_sub(bn_t *r, const bn_t *a, const bn_t *b) {    if (!r || !a || !b) return BN_ERR_NULL_PTR;        int cmp = bn_cmp(a, b);    if (cmp &lt; 0) {        return BN_ERR_ALL_NEGATIVE_RESULT;    }if (cmp == 0) {        bn_set_zero(r);        return BN_SUCCESS;    }    // 原地操作处理    if (r == a || r == b) {        bn_t temp;        bn_init(&amp;temp, 0);        bn_err_t err = bn_sub(&amp;temp, a, b);        if (err != BN_SUCCESS) {            bn_free(&amp;temp);            return err;        }        err = bn_copy(r, &amp;temp);        bn_free(&amp;temp);        return err;    }        int max_digs = a-&gt;used_digs;    bn_err_t err = bn_ensure_capacity(r, max_digs);    if (err != BN_SUCCESS) return err;        // 清零    memset(r-&gt;data, 0, r-&gt;capacity * sizeof(dig_t));        uint64_t borrow = 0;        // 逐位相减    for (int i = 0; i &lt; max_digs; i++) {        uint64_t a_val = (uint64_t)a-&gt;data[i];        uint64_t b_val = (i &lt; b-&gt;used_digs) ? (uint64_t)b-&gt;data[i] : 0;        b_val += borrow;  // 加上之前的借位                if (a_val &lt; b_val) {            // 需要借位            a_val += ((uint64_t)1 &lt;&lt; WBITS);            borrow = 1;        } else {            borrow = 0;        }                r-&gt;data[i] = (dig_t)(a_val - b_val);    }        r-&gt;used_digs = max_digs;        while (r-&gt;used_digs &gt; 0 &amp;&amp; r-&gt;data[r-&gt;used_digs - 1] == 0) {        r-&gt;used_digs--;    }        return BN_SUCCESS;}
既然有得到正数的减法，如何实现一个得到负数的减法，毕竟拓展欧几里得算法中间是会出现负数的
于是灵光一闪，使用错误码返回代表是正数是负数，BN_SUCCESS代表非负数，BN_ERR_ALL_NEGATIVE_RESULT代表负数
bn_err_t bn_sub_signed(bn_t *r, const bn_t *a, const bn_t *b) {    if (!r || !a || !b) return BN_ERR_NULL_PTR;    int cmp = bn_cmp(a, b);    if (cmp == 0) {        bn_set_zero(r);        return BN_SUCCESS;    }    if (r == a || r == b) {        bn_t temp;        bn_init(&amp;temp, 0);        bn_err_t err = bn_sub_signed(&amp;temp, a, b);        if (err != BN_SUCCESS &amp;&amp; err != BN_ERR_ALL_NEGATIVE_RESULT) {            bn_free(&amp;temp);            return err;        }        bn_copy(r, &amp;temp);        bn_free(&amp;temp);        return err;  // 保持原返回值    }        int max_digs = MAX(a-&gt;used_digs, b-&gt;used_digs);    bn_err_t err = bn_ensure_capacity(r, max_digs);    if (err != BN_SUCCESS) return err;        memset(r-&gt;data, 0, r-&gt;capacity * sizeof(dig_t));        uint64_t borrow = 0;        if (cmp &gt;= 0) {        for (int i = 0; i &lt; a-&gt;used_digs; i++) {            uint64_t a_val = (uint64_t)a-&gt;data[i];            uint64_t b_val = (i &lt; b-&gt;used_digs) ? (uint64_t)b-&gt;data[i] : 0;            b_val += borrow;            if (a_val &lt; b_val) {                a_val += ((uint64_t)1 &lt;&lt; WBITS);                borrow = 1;            } else {                borrow = 0;            }            r-&gt;data[i] = (dig_t)(a_val - b_val);        }    } else {        for (int i = 0; i &lt; b-&gt;used_digs; i++) {            uint64_t b_val = (uint64_t)b-&gt;data[i];            uint64_t a_val = (i &lt; a-&gt;used_digs) ? (uint64_t)a-&gt;data[i] : 0;            a_val += borrow;            if (b_val &lt; a_val) {                b_val += ((uint64_t)1 &lt;&lt; WBITS);                borrow = 1;            } else {                borrow = 0;            }            r-&gt;data[i] = (dig_t)(b_val - a_val);        }    }    r-&gt;used_digs = max_digs;    while (r-&gt;used_digs &gt; 0 &amp;&amp; r-&gt;data[r-&gt;used_digs - 1] == 0) {        r-&gt;used_digs--;    }    if (cmp &gt;= 0) {        return BN_SUCCESS;  // 结果为正    } else {        return BN_ERR_ALL_NEGATIVE_RESULT;  // 结果为负    }}
假如不使用错误码判断呢，那再拓展一下，传入一个变量来判断是否是正数
bn_err_t bn_sub_with_sign(bn_t *r, int *is_negative, const bn_t *a, const bn_t *b) {    if (!r || !is_negative || !a || !b) return BN_ERR_NULL_PTR;        bn_err_t err = bn_sub_signed(r, a, b);        if (err == BN_SUCCESS) {        *is_negative = 0;        return BN_SUCCESS;    } else if (err == BN_ERR_ALL_NEGATIVE_RESULT) {        *is_negative = 1;        return BN_SUCCESS;    } else {        return err;    }}
然后是乘法
bn_err_t bn_mul(bn_t *r, const bn_t *a, const bn_t *b) {    if (!r || !a || !b) return BN_ERR_NULL_PTR;    if (bn_is_zero(a) || bn_is_zero(b)){        return bn_set_zero(r);    }    if (bn_is_one(a)) {        return bn_copy(r, b);    }    if (bn_is_one(b)) {        return bn_copy(r, a);    }    if (r == a || r == b) {        bn_t temp;        bn_init(&amp;temp, 0);        bn_err_t err = bn_mul(&amp;temp, a, b);        if (err == BN_SUCCESS) {            err = bn_copy(r, &amp;temp);        }        bn_free(&amp;temp);        return err;    }        int result_digs = a-&gt;used_digs + b-&gt;used_digs;    bn_err_t err = bn_ensure_capacity(r, result_digs);    if (err != BN_SUCCESS) return err;        memset(r-&gt;data, 0, r-&gt;capacity * sizeof(dig_t));        for (int i = 0; i &lt; a-&gt;used_digs; i++) {        if (a-&gt;data[i] == 0) continue;                uint64_t carry = 0;        for (int j = 0; j &lt; b-&gt;used_digs; j++) {            carry += (uint64_t)r-&gt;data[i + j] + (uint64_t)a-&gt;data[i] * b-&gt;data[j];            r-&gt;data[i + j] = (dig_t)(carry &amp; DIG_MASK);            carry &gt;&gt;= WBITS;        }                // 处理最后的进位        int k = i + b-&gt;used_digs;        while (carry &gt; 0 &amp;&amp; k &lt; result_digs) {            carry += r-&gt;data[k];            r-&gt;data[k] = (dig_t)(carry &amp; DIG_MASK);            carry &gt;&gt;= WBITS;            k++;        }    }        r-&gt;used_digs = result_digs;    while (r-&gt;used_digs &gt; 0 &amp;&amp; r-&gt;data[r-&gt;used_digs - 1] == 0) {        r-&gt;used_digs--;    }        return BN_SUCCESS;}
平方运算
bn_err_t bn_sqr(bn_t *r, const bn_t *a) {    return bn_mul(r, a, a);}
左移和右移
bn_err_t bn_lsh(bn_t *r, const bn_t *a, int bits) {    if (!r || !a) return BN_ERR_NULL_PTR;    if (bits &lt; 0) return BN_ERR_INVALID_PARAM;    if (bits == 0) return bn_copy(r, a);        if (r == a) {        bn_t temp;        bn_init(&amp;temp, 0);        bn_err_t err = bn_lsh(&amp;temp, a, bits);        if (err == BN_SUCCESS) {            err = bn_copy(r, &amp;temp);        }        bn_free(&amp;temp);        return err;    }    int dig_shift = bits / WBITS;    int bit_shift = bits % WBITS;    int result_digs = a-&gt;used_digs + dig_shift + (bit_shift &gt; 0 ? 1 : 0);        bn_err_t err = bn_ensure_capacity(r, result_digs);    if (err != BN_SUCCESS) return err;        memset(r-&gt;data, 0, r-&gt;capacity * sizeof(dig_t));        if (bit_shift == 0) {        memcpy(r-&gt;data + dig_shift, a-&gt;data, a-&gt;used_digs * sizeof(dig_t));    } else {        uint64_t carry = 0;        for (int i = 0; i &lt; a-&gt;used_digs; i++) {            uint64_t val = ((uint64_t)a-&gt;data[i] &lt;&lt; bit_shift) | carry;            r-&gt;data[i + dig_shift] = (dig_t)(val &amp; DIG_MASK);            carry = val &gt;&gt; WBITS;        }        if (carry &gt; 0) {            r-&gt;data[a-&gt;used_digs + dig_shift] = (dig_t)carry;        }    }        r-&gt;used_digs = result_digs;    while (r-&gt;used_digs &gt; 0 &amp;&amp; r-&gt;data[r-&gt;used_digs - 1] == 0) {        r-&gt;used_digs--;    }        return BN_SUCCESS;}bn_err_t bn_rsh(bn_t *r, const bn_t *a, int bits) {    if (!r || !a) return BN_ERR_NULL_PTR;    if (bits &lt; 0) return BN_ERR_INVALID_PARAM;        if (bits == 0) return bn_copy(r, a);        if (bn_is_zero(a)) {        return bn_set_zero(r);    }        int dig_shift = bits / WBITS;    int bit_shift = bits % WBITS;        if (dig_shift &gt;= a-&gt;used_digs) {        return bn_set_zero(r);    }        if (r == a) {        bn_t temp;        bn_init(&amp;temp, 0);        bn_err_t err = bn_rsh(&amp;temp, a, bits);        if (err == BN_SUCCESS) {            err = bn_copy(r, &amp;temp);        }        bn_free(&amp;temp);        return err;    }        int max_result_digs = a-&gt;used_digs - dig_shift;        bn_err_t err = bn_ensure_capacity(r, max_result_digs);    if (err != BN_SUCCESS) return err;        memset(r-&gt;data, 0, r-&gt;capacity * sizeof(dig_t));        if (bit_shift == 0) {        memcpy(r-&gt;data, a-&gt;data + dig_shift, max_result_digs * sizeof(dig_t));        r-&gt;used_digs = max_result_digs;    } else {        // 从最低的有效位置开始处理        for (int src_idx = dig_shift; src_idx &lt; a-&gt;used_digs; src_idx++) {            int dst_idx = src_idx - dig_shift;            // 获取当前字            dig_t current_word = a-&gt;data[src_idx];            // 获取下一个（更高）字用于进位            dig_t next_word = (src_idx + 1 &lt; a-&gt;used_digs) ? a-&gt;data[src_idx + 1] : 0;            // 当前字的低位部分（右移后保留的部分）            dig_t low_part = current_word &gt;&gt; bit_shift;            // 下一个字的高位部分（作为进位）需要左移 (WBITS - bit_shift) 位            int carry_shift = WBITS - bit_shift;            dig_t carry_part = 0;            if (carry_shift &lt; WBITS) {  // 避免移位超过字长                carry_part = next_word &lt;&lt; carry_shift;            }            // 组合结果            r-&gt;data[dst_idx] = low_part | carry_part;        }                r-&gt;used_digs = max_result_digs;    }        while (r-&gt;used_digs &gt; 0 &amp;&amp; r-&gt;data[r-&gt;used_digs - 1] == 0) {        r-&gt;used_digs--;    }        if (r-&gt;used_digs == 0) {        r-&gt;used_digs = 1;        r-&gt;data[0] = 0;    }        return BN_SUCCESS;}
实现了大精度加法，为了加快小精度的速度，添加了对一个dig的特殊操作
dig_t bn_add_dig(bn_t *r, const bn_t *a, dig_t b) {    if (!r || !a) return 0;    if (b == 0) {        bn_copy(r, a);        return 0;    }    if (bn_is_zero(a)){        if(!(r-&gt;data)) bn_init(r, 1);        memset(r-&gt;data, 0, r-&gt;capacity * sizeof(dig_t));        r-&gt;data[0] = b;        r-&gt;used_digs = 1;        return 0;    }    bn_err_t err = bn_ensure_capacity(r, a-&gt;used_digs + 1);    if(err != BN_SUCCESS) return 0;    if(r != a){        err = bn_copy(r, a);        if(err != BN_SUCCESS) return 0;    }    uint64_t carry = b;    for (int i = 0; i &lt; r-&gt;used_digs &amp;&amp; carry &gt; 0; i++) {        carry += r-&gt;data[i];        r-&gt;data[i] = (dig_t)(carry &amp; DIG_MASK);        carry &gt;&gt;= WBITS;    }        if (carry &gt; 0) {        r-&gt;data[r-&gt;used_digs] = (dig_t)carry;        r-&gt;used_digs++;    }        while (r-&gt;used_digs &gt; 0 &amp;&amp; r-&gt;data[r-&gt;used_digs - 1] == 0) {        r-&gt;used_digs--;    }        return (dig_t)carry;}dig_t bn_sub_dig(bn_t *r, const bn_t *a, dig_t b) {    if (!r || !a) return 1;    if (a-&gt;used_digs ==0 ) return 0;    if ( a-&gt;used_digs == 1 &amp;&amp; a-&gt;data[0] &lt;= b ){        if(a-&gt;data[0] == b) {            bn_set_zero(r);            return 0;        }        return 1;    }    if (b == 0) {        bn_copy(r, a);        return 0;    }        if(r != a){        bn_err_t err = bn_copy(r, a);        if(err != BN_SUCCESS) return 0;    }        uint64_t borrow = b;    for (int i = 0; i &lt; r-&gt;used_digs &amp;&amp; borrow &gt; 0; i++) {        if (r-&gt;data[i] &lt; borrow) {            r-&gt;data[i] = (dig_t)((1ULL &lt;&lt; WBITS) + r-&gt;data[i] - borrow);            borrow = 1;        } else {            r-&gt;data[i] -= (dig_t)borrow;            borrow = 0;            break;        }    }        while (r-&gt;used_digs &gt; 0 &amp;&amp; r-&gt;data[r-&gt;used_digs - 1] == 0) {        r-&gt;used_digs--;    }        return (dig_t)borrow;}
然后是除法运算，这个主要是针对相差不大的数字
bn_err_t bn_div(bn_t *q, bn_t *r, const bn_t *a, const bn_t *b) {    if (!q || !r || !a || !b) return BN_ERR_NULL_PTR;    if (bn_is_zero(b)) return BN_ERR_INVALID_PARAM;        int cmp = bn_cmp(a, b);    if (cmp &lt; 0) {        bn_set_zero(q);        bn_copy(r, a);        return BN_SUCCESS;    }    if (cmp == 0) {        bn_set_one(q);        bn_set_zero(r);        return BN_SUCCESS;    }        bn_t a1, q1, temp;        int cap = a-&gt;capacity + 1;    bn_init(&amp;a1, cap);    bn_init(&amp;q1, cap);    bn_init(&amp;temp, cap);        bn_copy(&amp;a1, a);    bn_set_zero(q);        int b_bits = bn_get_bits(b);    while (bn_cmp(&amp;a1, b) &gt;= 0) {        bn_set_one(&amp;q1);        int shift = bn_get_bits(&amp;a1) - b_bits;        while (shift &gt;= 0) {            bn_lsh(&amp;temp, b, shift);            if (bn_cmp(&amp;temp, &amp;a1) &lt;= 0) {                break;            }            shift--;        }        if(shift &lt; 0) break;        bn_lsh(&amp;q1, &amp;q1, shift);        bn_add(q, q, &amp;q1);        bn_sub(&amp;a1, &amp;a1, &amp;temp);    }    // while (bn_cmp(&amp;a1, b) &gt;= 0) {		// 相差比较大的时候开销就很大了    //     bn_set_one(&amp;q1);    //     int shift = 0;    //     while (1) {    //         bn_lsh(&amp;temp, b, shift+1);    //         if (bn_cmp(&amp;temp, &amp;a1) &gt; 0) {    //             break;    //         }    //         shift++;    //     }    //     bn_lsh(&amp;q1, &amp;q1, shift);    //     bn_add(q, q, &amp;q1);    //     bn_rsh(r, &amp;temp, 1);    //     bn_sub(&amp;a1, &amp;a1, r);    // }    bn_copy(r, &amp;a1);    bn_free(&amp;a1);    bn_free(&amp;q1);    bn_free(&amp;temp);        return BN_SUCCESS;}
还有取模运算
bn_err_t bn_mod(bn_t *r, const bn_t *a, const bn_t *m) {    if (!r || !a || !m) return BN_ERR_NULL_PTR;    if (bn_is_zero(m)) return BN_ERR_INVALID_PARAM;    int cmp = bn_cmp(a, m);    if (cmp &lt; 0) {        bn_copy(r, a);        return BN_SUCCESS;    }    if (cmp == 0) {        bn_set_zero(r);        return BN_SUCCESS;    }    if (r == a || r == m){        bn_t temp;        bn_init(&amp;temp, a-&gt;used_digs);        bn_err_t err = bn_mod(&amp;temp, a, m);        if (err == BN_SUCCESS) {            err = bn_copy(r, &amp;temp);        }        bn_free(&amp;temp);        return err;    }    bn_t a1, temp;        int cap = a-&gt;capacity + 1;    bn_init(&amp;a1, cap);    bn_init(&amp;temp, cap);        bn_copy(&amp;a1, a);        int m_bits = bn_get_bits(m);    while (bn_cmp(&amp;a1, m) &gt;= 0) {        int a1_bits = bn_get_bits(&amp;a1);        int shift = a1_bits - m_bits;        while (shift &gt;= 0) {            bn_lsh(&amp;temp, m, shift);            if (bn_cmp(&amp;temp, &amp;a1) &lt;= 0) {                break;            }            shift--;        }        if(shift &lt; 0) break;        bn_sub(&amp;a1, &amp;a1, &amp;temp);    }    // while (bn_cmp(&amp;a1, m) &gt;= 0) {	// 一样是改进了这个    //     bn_set_one(&amp;q1);    //     int shift = 0;    //     while (1) {    //         bn_lsh(&amp;temp, m, shift+1);    //         if (bn_cmp(&amp;temp, &amp;a1) &gt; 0) {    //             break;    //         }    //         shift++;    //     }    //     bn_rsh(r, &amp;temp, 1);    //     bn_sub(&amp;a1, &amp;a1, r);    // }    bn_copy(r, &amp;a1);    bn_free(&amp;a1);    bn_free(&amp;temp);        return BN_SUCCESS;    // bn_t q;    // bn_init(&amp;q, a-&gt;capacity);        // bn_err_t err = bn_div(&amp;q, r, a, m);    // bn_free(&amp;q);        //return err;}
模运算
一般的模加、模减、模乘
这里我没使用bn_mod是因为数比较接近，使用bn_mod的时间开销大，于是便使用了时间开销更小的bn_sub
bn_err_t bn_mod_add(bn_t *r, const bn_t *a, const bn_t *b, const bn_t *m) {    if (!r || !a || !b || !m) return BN_ERR_NULL_PTR;    if (bn_is_zero(m)) return BN_ERR_INVALID_PARAM;        if (bn_is_zero(a)) return bn_mod_sub(r, b, a, m);    if (bn_is_zero(b)) return bn_mod_sub(r, a, b, m);            bn_t sum;    int max_capacity = (a-&gt;used_digs &gt; b-&gt;used_digs ? a-&gt;used_digs : b-&gt;used_digs) + 1;    bn_init(&amp;sum, max_capacity);        bn_err_t err = bn_add(&amp;sum, a, b);    if (err != BN_SUCCESS) {        bn_free(&amp;sum);        return err;    }        //bn_mod(&amp;sum,&amp;sum,m);    while (bn_cmp(&amp;sum, m) &gt;= 0) {        err = bn_sub(&amp;sum, &amp;sum, m);        if (err != BN_SUCCESS) {            bn_free(&amp;sum);            return err;        }    }        if (r != &amp;sum) {        err = bn_copy(r, &amp;sum);    }    bn_free(&amp;sum);    return err ? err : BN_SUCCESS;}bn_err_t bn_mod_sub(bn_t *r, const bn_t *a, const bn_t *b, const bn_t *m) {    if (!r || !a || !b || !m) return BN_ERR_NULL_PTR;    if (bn_is_zero(m)) return BN_ERR_INVALID_PARAM;        bn_t a_mod, b_mod;    bn_init(&amp;a_mod, m-&gt;used_digs);    bn_init(&amp;b_mod, m-&gt;used_digs);        //bn_mod(&amp;a_mod, a, m);    bn_copy(&amp;a_mod,a);    while(bn_cmp(a,m)&gt;=0){        bn_sub(&amp;a_mod,&amp;a_mod,m);    }    //bn_mod(&amp;b_mod, b, m);    bn_copy(&amp;b_mod,b);    while(bn_cmp(b,m)&gt;=0){        bn_sub(&amp;b_mod,&amp;b_mod,m);    }    int cmp = bn_cmp(&amp;a_mod, &amp;b_mod);    if (cmp &gt;= 0) {        bn_sub(r, &amp;a_mod, &amp;b_mod);    } else {        bn_t temp;        bn_init(&amp;temp, m-&gt;used_digs);        bn_sub(&amp;temp, m, &amp;b_mod);        bn_add(r, &amp;a_mod, &amp;temp);                bn_free(&amp;temp);        if (bn_cmp(r, m) &gt;= 0) {            bn_sub(r, r, m);        }    }        bn_free(&amp;a_mod);    bn_free(&amp;b_mod);    return BN_SUCCESS;}bn_err_t bn_mod_mul(bn_t *r, const bn_t *a, const bn_t *b, const bn_t *m) {    if (!r || !a || !b || !m) return BN_ERR_NULL_PTR;    if (bn_is_zero(m)) return BN_ERR_INVALID_PARAM;    if (bn_is_even(m)) return BN_ERR_MODULUS_EVEN;    bn_t temp;    bn_err_t err = bn_init(&amp;temp,a-&gt;capacity+b-&gt;used_digs);    if(err!=BN_SUCCESS) return BN_ERR_MEMORY;    bn_mul(&amp;temp,a,b);    if(err!=BN_SUCCESS) return BN_ERR_INVALID_PARAM;    bn_mod(r,&amp;temp,m);    if(err!=BN_SUCCESS) return BN_ERR_INVALID_PARAM;    bn_free(&amp;temp);    return err;}bn_err_t bn_mod_sqr(bn_t *r, const bn_t *a, const bn_t *m) {    return bn_mod_mul(r, a, a, m);}bn_err_t bn_mod_exp(bn_t *r, const bn_t *a, const bn_t *e, const bn_t *m) {    if (!r || !a || !e || !m) return BN_ERR_NULL_PTR;    if (bn_is_zero(m)) return BN_ERR_INVALID_PARAM;        if (bn_is_zero(e)) {        return bn_set_one(r);    }    if (bn_is_one(e)) {        bn_t one;        bn_init(&amp;one, 0);        bn_set_one(&amp;one);        bn_err_t err = bn_mod_mul_mont(r, a, &amp;one, m);        bn_free(&amp;one);        return err;    }    bn_t result, base, exp;    bn_init(&amp;result, 0);    bn_init(&amp;base, 0);    bn_init(&amp;exp, 0);    bn_err_t err = bn_copy(&amp;base, a);    if (err) goto cleanup;    err = bn_copy(&amp;exp, e);    if (err) goto cleanup;    bn_set_one(&amp;result);    while (!bn_is_zero(&amp;exp)) {        if (bn_is_even(&amp;exp)) {            bn_t temp;            bn_init(&amp;temp, 0);            err = bn_mod_mul(&amp;temp, &amp;base, &amp;base, m);            if (err) {                bn_free(&amp;temp);                goto cleanup;            }            bn_copy(&amp;base, &amp;temp);            bn_free(&amp;temp);                        bn_rsh(&amp;exp, &amp;exp, 1);        } else {            bn_t temp;            bn_init(&amp;temp, 0);            err = bn_mod_mul(&amp;temp, &amp;result, &amp;base, m);            if (err) {                bn_free(&amp;temp);                goto cleanup;            }            bn_copy(&amp;result, &amp;temp);            bn_free(&amp;temp);                        bn_t one;            bn_init(&amp;one, 0);            bn_set_one(&amp;one);            err = bn_sub(&amp;exp, &amp;exp, &amp;one);            bn_free(&amp;one);            if (err) goto cleanup;        }    }        err = bn_copy(r, &amp;result);cleanup:    bn_free(&amp;result);    bn_free(&amp;base);    bn_free(&amp;exp);    return err;}
还有模折半
bn_err_t bn_mod_hlv(bn_t *r, const bn_t *a, const bn_t *m) {    if (!r || !a || !m) return BN_ERR_NULL_PTR;    if (bn_is_zero(m)) return BN_ERR_INVALID_PARAM;        bn_t a_reduced;    bn_init(&amp;a_reduced, a-&gt;used_digs);    bn_copy(&amp;a_reduced, a);        // while (bn_cmp(&amp;a_reduced, m) &gt;= 0) {    //     bn_sub(&amp;a_reduced, &amp;a_reduced, m);    // }    bn_mod(&amp;a_reduced, a, m);    bn_err_t err;        if (bn_is_even(&amp;a_reduced)) {        err = bn_rsh(r, &amp;a_reduced, 1);        if (err != BN_SUCCESS) {            bn_free(&amp;a_reduced);            return err;        }    } else {        bn_t sum;        bn_init(&amp;sum, (a_reduced.used_digs &gt; m-&gt;used_digs ?                       a_reduced.used_digs : m-&gt;used_digs) + 1);        err = bn_add(&amp;sum, &amp;a_reduced, m);        if (err != BN_SUCCESS) {            bn_free(&amp;a_reduced);            bn_free(&amp;sum);            return err;        }        err = bn_rsh(r, &amp;sum, 1);        bn_free(&amp;sum);        if (err != BN_SUCCESS) {            bn_free(&amp;a_reduced);            return err;        }    }        bn_free(&amp;a_reduced);    return BN_SUCCESS;}
进阶模运算
求逆元是模运算中比较常用的
有拓展欧几里得算法，但是这个好像在我的大整数运算中开销特别大，于是后来我改进成了牛顿迭代法，毕竟完成的模乘和模幂等等只需要求的逆元，使用牛顿迭代法特别快
首先是拓展欧几里得算法，因为我还没实现负数的运算，只能使用返回错误码来判断回溯是两个值的正负性
   BN_SUCCESS = 0,BN_ERR_ALL_NEGATIVE_RESULT = -10,   BN_ERR_FIRST_NEGATIVE_RESULT = -11,   BN_ERR_SECOND_NEGATIVE_RESULT = -12,
也算是比较巧思了吧
bn_err_t extended_gcd(bn_t *gcd, bn_t *x, bn_t *y, const bn_t *a, const bn_t *b) {    if (!gcd || !x || !y || !a || !b) return BN_ERR_NULL_PTR;    if (bn_is_zero(b)) {        bn_copy(gcd, a);        bn_set_one(x);        bn_set_zero(y);        return BN_SUCCESS;    }        bn_t q, r, x1, y1, product, temp;    int cap = a-&gt;capacity &gt; b-&gt;capacity ? a-&gt;capacity : b-&gt;capacity;    cap += 2;        bn_init(&amp;q, cap);    bn_init(&amp;r, cap);    bn_init(&amp;x1, cap);    bn_init(&amp;y1, cap);    bn_init(&amp;product, cap);    bn_init(&amp;temp, cap);    bn_set_zero(&amp;x1);    bn_set_zero(&amp;y1);    bn_set_zero(&amp;q);    bn_set_zero(&amp;r);    bn_div(&amp;q, &amp;r, a, b);        bn_err_t err = extended_gcd(gcd, &amp;x1, &amp;y1, b, &amp;r);    bn_copy(x, &amp;y1);    bn_mul(&amp;product, &amp;q, &amp;y1);        // printf("err before %d ",err);    if(err == BN_ERR_FIRST_NEGATIVE_RESULT){        bn_add(y,&amp;product,&amp;x1);        err=BN_ERR_SECOND_NEGATIVE_RESULT;    }    else if(err == BN_ERR_SECOND_NEGATIVE_RESULT){        bn_add(y,&amp;product,&amp;x1);        err = BN_ERR_FIRST_NEGATIVE_RESULT;    }    else if(err == BN_SUCCESS){        if(bn_cmp(&amp;x1, &amp;product) &gt;= 0){            bn_sub(y, &amp;x1, &amp;product);            err = BN_SUCCESS;        }else{            bn_sub(y, &amp;product, &amp;x1);            err = BN_ERR_SECOND_NEGATIVE_RESULT;        }    }    else{        if(bn_cmp(&amp;x1, &amp;product) &lt;= 0){            bn_sub(y, &amp;product, &amp;x1);            err = BN_ERR_FIRST_NEGATIVE_RESULT;        }else{            bn_sub(y, &amp;x1, &amp;product);            err = BN_ERR_ALL_NEGATIVE_RESULT;        }    }    // printf("err after %d ",err);    // bn_print(&amp;x1,"x1 ");    // bn_print(&amp;y1,"y1 ");    // bn_print(&amp;q,"q ");    // bn_print(&amp;r,"r ");    // bn_print(&amp;product,"product ");    bn_free(&amp;q);    bn_free(&amp;r);    bn_free(&amp;x1);    bn_free(&amp;y1);    bn_free(&amp;product);    bn_free(&amp;temp);        return err;}bn_err_t bn_mod_inv(bn_t *inv, const bn_t *a, const bn_t *m) {    if (!inv || !a || !m) return BN_ERR_NULL_PTR;    if (bn_is_zero(m) || bn_is_zero(a)) return BN_ERR_INVALID_PARAM;            bn_t a_mod_m;    bn_init(&amp;a_mod_m, m-&gt;capacity + 1);    bn_mod(&amp;a_mod_m, a, m);        if (bn_is_zero(&amp;a_mod_m)) {        bn_free(&amp;a_mod_m);        return BN_ERR_NO_INVERSE;    }    int cap = m-&gt;capacity + 2;    bn_t one;    bn_init(&amp;one, cap);    bn_set_one(&amp;one);        if (bn_cmp(&amp;a_mod_m, &amp;one) == 0) {        bn_copy(inv, &amp;one);        bn_free(&amp;one);        bn_free(&amp;a_mod_m);        return BN_SUCCESS;    }        bn_t gcd, x, y;        bn_init(&amp;gcd, cap);    bn_init(&amp;x, cap);    bn_init(&amp;y, cap);    bn_set_zero(&amp;gcd);    bn_set_zero(&amp;x);    bn_set_zero(&amp;y);        bn_err_t err = extended_gcd(&amp;gcd, &amp;x, &amp;y, &amp;a_mod_m, m);    if(bn_cmp(&amp;gcd,&amp;one)!=0){        err = BN_ERR_NO_INVERSE;        goto cleanup_all;    }    bn_t temp1;    bn_init(&amp;temp1,cap);    bn_set_zero(&amp;temp1);    if(err==BN_ERR_FIRST_NEGATIVE_RESULT || err == BN_ERR_ALL_NEGATIVE_RESULT){        bn_sub(inv,m,&amp;x);        err = BN_SUCCESS;    }    else{        bn_copy(inv,&amp;x);        err = BN_SUCCESS;    }    bn_free(&amp;temp1);    cleanup_all:    bn_free(&amp;gcd);    bn_free(&amp;x);    bn_free(&amp;y);    bn_free(&amp;one);    bn_free(&amp;a_mod_m);        return err;}
牛顿迭代法
bn_err_t bn_mod_inv_usedNewton(bn_t *inv, const bn_t *N, const bn_t *R, const int k){    if (!inv || !N || !R) return BN_ERR_NULL_PTR;    if (bn_is_zero(N) || bn_is_zero(R)) return BN_ERR_INVALID_PARAM;    bn_t inv_0, temp_t, one, two, temp_1;    bn_init(&amp;inv_0, 2*R-&gt;used_digs);    bn_init(&amp;temp_t, 2*R-&gt;used_digs);    bn_init(&amp;temp_1, 2*R-&gt;used_digs);    bn_init(&amp;one, 1);    bn_init(&amp;two, 1);    bn_set_one(&amp;one);    bn_set_one(&amp;inv_0);    bn_set_one(&amp;temp_t);    bn_set_zero(&amp;temp_1);    (&amp;two)-&gt;data[0] = 2;    (&amp;two)-&gt;used_digs = 1;    for(int i = 1; i&lt;k ;i &lt;&lt;= 1){        bn_mul(&amp;temp_t, N, &amp;inv_0);        if(bn_cmp(&amp;two,&amp;temp_t)&gt;=0){            bn_sub(&amp;temp_t,&amp;two, &amp;temp_t);        }else{            bn_sub(&amp;temp_t,&amp;temp_t,&amp;two);            bn_truncate_bits(&amp;temp_t, MIN(k, 2*i));            bn_lsh(&amp;temp_1, &amp;one, MIN(k,2*i));            bn_sub(&amp;temp_t,&amp;temp_1, &amp;temp_t);        }        bn_mul(&amp;inv_0, &amp;inv_0, &amp;temp_t);        bn_truncate_bits(&amp;inv_0, MIN(k, 2*i));    }    bn_copy(inv,&amp;inv_0);    bn_free(&amp;inv_0);    bn_free(&amp;temp_1);    bn_free(&amp;temp_t);    bn_free(&amp;two);    bn_free(&amp;one);    return BN_SUCCESS;}
蒙哥马利算法
使用一个结构体储存我们预计算的蒙哥马利上下文
bn_err_t mont_ctx_init(mont_ctx_t *ctx, const bn_t *N) {    if (!ctx || !N) return BN_ERR_NULL_PTR;    if (bn_is_even(N)) return BN_ERR_MODULUS_EVEN;    memset(ctx, 0, sizeof(mont_ctx_t));        bn_err_t err = bn_copy(&amp;ctx-&gt;N, N);    if (err != BN_SUCCESS) return err;    ctx-&gt;k = bn_get_bits(N);    ctx-&gt;k_digs = (ctx-&gt;k + WBITS - 1) / WBITS;        err = mont_compute_R(&amp;ctx-&gt;R, N, &amp;ctx-&gt;k);    if (err != BN_SUCCESS) {        bn_free(&amp;ctx-&gt;N);        return err;    }        err = mont_compute_N_prime(&amp;ctx-&gt;N_prime, N, &amp;ctx-&gt;R);    if (err != BN_SUCCESS) {        bn_free(&amp;ctx-&gt;N);        bn_free(&amp;ctx-&gt;R);        return err;    }        bn_t R2_pre;    bn_init(&amp;R2_pre, (ctx-&gt;k_digs)*2);    bn_mul(&amp;R2_pre, &amp;ctx-&gt;R, &amp;ctx-&gt;R);    err = bn_mod(&amp;ctx-&gt;R2, &amp;R2_pre, N);    bn_free(&amp;R2_pre);    if (err != BN_SUCCESS) {        bn_free(&amp;ctx-&gt;N);        bn_free(&amp;ctx-&gt;R);        bn_free(&amp;ctx-&gt;N_prime);        return err;    }    return BN_SUCCESS;}void mont_ctx_free(mont_ctx_t *ctx) {    if (ctx) {        bn_free(&amp;ctx-&gt;N);        bn_free(&amp;ctx-&gt;R);        bn_free(&amp;ctx-&gt;N_prime);        bn_free(&amp;ctx-&gt;R2);        memset(ctx, 0, sizeof(mont_ctx_t));    }}bn_err_t mont_ctx_compute(mont_ctx_t *ctx, const bn_t *N) {    mont_ctx_free(ctx);    return mont_ctx_init(ctx, N);}
首先是计算我们的R的位数，使用bn_get_bits就可以了
bn_err_t mont_compute_R(bn_t *R, const bn_t *N, int *k) {    if (!R || !N) return BN_ERR_NULL_PTR;        *k = bn_get_bits(N);    bn_err_t err = bn_set_one(R);    if (err != BN_SUCCESS) return err;        return bn_lsh(R, R, *k);}
然后是构造我们的R，使用bn_set_bit设置我们上面得到的位为1
然后是另一个很重要的参数  先计算出逆元再相减
bn_err_t mont_compute_N_prime(bn_t *N_prime, const bn_t *N, const bn_t *R) {    if (!N_prime || !N || !R) return BN_ERR_NULL_PTR;    int k = bn_get_bits(N);    int k_digs = (k + WBITS - 1) / WBITS;        bn_t inv;    bn_init(&amp;inv, 0);        bn_err_t err = bn_mod_inv_usedNewton(&amp;inv, N, R, k);    if (err) goto cleanup;        err = bn_sub(N_prime, R, &amp;inv);cleanup:    bn_free(&amp;inv);    return err;}
R2就是，便于我们进行蒙哥马利域转换
转换为蒙哥马利形式
bn_err_t mont_map(bn_t *a_mont, const bn_t *a, const mont_ctx_t *ctx) {    if (!a_mont || !a || !ctx) return BN_ERR_NULL_PTR;    bn_t aR2;    bn_init(&amp;aR2, (ctx-&gt;k_digs)*2);    bn_set_zero(&amp;aR2);    bn_err_t err = bn_mul(&amp;aR2, a, &amp;ctx-&gt;R2);    if (err != BN_SUCCESS) {        bn_free(&amp;aR2);        return err;    }    err = mont_redc_internal(a_mont, &amp;aR2, &amp;ctx-&gt;N, &amp;ctx-&gt;N_prime, ctx-&gt;k);        bn_free(&amp;aR2);    return err;}
使用模约减返回  调用原来的上下文就可以避免重复计算
bn_err_t mont_reduce(bn_t *a, const bn_t *a_mont, const mont_ctx_t *ctx) {    if (!a || !a_mont || !ctx) return BN_ERR_NULL_PTR;    return mont_redc_internal(a, a_mont, &amp;ctx-&gt;N, &amp;ctx-&gt;N_prime, ctx-&gt;k);}
调用的函数是
bn_err_t mont_redc_internal(bn_t *r, const bn_t *T, const bn_t *N, const bn_t *N_prime, int k) {    if (!r || !T || !N || !N_prime) return BN_ERR_NULL_PTR;        int k_digs = (k + WBITS - 1) / WBITS;    bn_err_t err;        bn_t temp_T,temp, R;    int T_capacity=T-&gt;capacity;    int N_capacity=N-&gt;capacity;    int max = (T_capacity&gt;=N_capacity)?T_capacity:N_capacity;    bn_init(&amp;temp_T, max*2);    bn_init(&amp;temp, max*2);    bn_init(&amp;R, max*2);    bn_set_zero(&amp;temp_T);    bn_set_zero(&amp;temp);    bn_set_zero(&amp;R);    bn_set_bit(&amp;R,k,1);    err = bn_copy(&amp;temp_T, T);    if (err) {        bn_free(&amp;temp_T);        return err;    }    bn_mul(&amp;temp, N_prime, &amp;temp_T);    bn_truncate_bits(&amp;temp,k);    while(bn_cmp(&amp;temp,&amp;R)&gt;=0){        bn_sub(&amp;temp,&amp;temp,&amp;R);    }    bn_mul(&amp;temp_T, N, &amp;temp);    bn_add(&amp;temp,&amp;temp_T,T);    err = bn_rsh(&amp;temp_T, &amp;temp, k);        if (bn_cmp(&amp;temp_T, N) &gt;= 0) {        err = bn_sub(r, &amp;temp_T, N);    }else{        bn_copy(r,&amp;temp_T);    }    bn_free(&amp;temp_T);    bn_free(&amp;temp);    return err;}
由于我们是按位截取的，所以循环减开销时间比较短，比起bn_mod速度快不少
然后就是我们的模乘和模幂的具体代码，都是经典算法
bn_err_t bn_mod_mul_mont(bn_t *r, const bn_t *a, const bn_t *b, const bn_t *m) {    if (!r || !a || !b || !m) return BN_ERR_NULL_PTR;    if (bn_is_zero(m)) return BN_ERR_INVALID_PARAM;    if (bn_is_even(m)) return BN_ERR_MODULUS_EVEN;    mont_ctx_t ctx;    bn_err_t err = mont_ctx_init(&amp;ctx, m);    if (err != BN_SUCCESS) return err;    bn_t a_mont, b_mont;    bn_init(&amp;a_mont, (&amp;ctx)-&gt;k_digs);    bn_init(&amp;b_mont, (&amp;ctx)-&gt;k_digs);    err = mont_map(&amp;a_mont, a, &amp;ctx);    if (err) goto cleanup;    err = mont_map(&amp;b_mont, b, &amp;ctx);    if (err) goto cleanup;    bn_t result_mont;    bn_init(&amp;result_mont, 0);    err = mont_mul(&amp;result_mont, &amp;a_mont, &amp;b_mont, &amp;ctx);    if (err) goto cleanup2;        err = mont_reduce(r, &amp;result_mont, &amp;ctx);    cleanup2:    bn_free(&amp;result_mont);cleanup:    bn_free(&amp;a_mont);    bn_free(&amp;b_mont);    mont_ctx_free(&amp;ctx);    return err;}bn_err_t mont_mul(bn_t *r, const bn_t *a, const bn_t *b, const mont_ctx_t *ctx) {    if (!r || !a || !b || !ctx) return BN_ERR_NULL_PTR;    bn_t T;    bn_init(&amp;T, 0);    bn_err_t err = bn_mul(&amp;T, a, b);    if (err != BN_SUCCESS) {        bn_free(&amp;T);        return err;    }    err = mont_redc_internal(r, &amp;T, &amp;ctx-&gt;N, &amp;ctx-&gt;N_prime, ctx-&gt;k);    bn_free(&amp;T);    return err;}
模幂算法也是
bn_err_t bn_mod_exp_mont(bn_t *r, const bn_t *a, const bn_t *e, const bn_t *m) {    if (!r || !a || !e || !m) return BN_ERR_NULL_PTR;    if (bn_is_zero(m)) return BN_ERR_INVALID_PARAM;    if (bn_is_even(m)) return BN_ERR_MODULUS_EVEN;    mont_ctx_t ctx;    bn_err_t err = mont_ctx_init(&amp;ctx, m);    if (err != BN_SUCCESS) return err;    bn_t a_mont;    bn_init(&amp;a_mont, 0);    err = mont_map(&amp;a_mont, a, &amp;ctx);    if (err) goto cleanup;    err = mont_exp(r, &amp;a_mont, e, &amp;ctx);    if (err) goto cleanup2;        err = mont_reduce(&amp;a_mont, r, &amp;ctx);    if (err == BN_SUCCESS) {        bn_copy(r, &amp;a_mont);    }    cleanup2:    bn_free(&amp;a_mont);cleanup:    mont_ctx_free(&amp;ctx);    return err;}bn_err_t mont_exp(bn_t *r, const bn_t *a, const bn_t *e, const mont_ctx_t *ctx) {    if (!r || !a || !e || !ctx) return BN_ERR_NULL_PTR;    bn_t result, base;    bn_init(&amp;result, 0);    bn_init(&amp;base, 0);        bn_err_t err = bn_copy(&amp;base, a);    if (err) goto cleanup;    bn_t one;    bn_init(&amp;one, 0);    bn_set_one(&amp;one);    err = mont_map(&amp;result, &amp;one, ctx);    bn_free(&amp;one);    if (err) goto cleanup;    bn_t temp;    bn_init(&amp;temp, 0);    int bits = bn_get_bits(e);    for (int i = bits - 1; i &gt;= 0; i--) {        err = mont_sqr(&amp;temp, &amp;result, ctx);        if (err) {            bn_free(&amp;temp);            goto cleanup;        }        bn_copy(&amp;result, &amp;temp);        if (bn_get_bit(e, i)) {            err = mont_mul(&amp;temp, &amp;result, &amp;base, ctx);            if (err) {                bn_free(&amp;temp);                goto cleanup;            }            bn_copy(&amp;result, &amp;temp);        }    }    err = bn_copy(r, &amp;result);    cleanup:    bn_free(&amp;temp);    bn_free(&amp;result);    bn_free(&amp;base);    return err;}
这就是我的代码啦
经过测试，速度如下，每一项都是随机的数据
+------------------------------------------------------------------------------++---    Bench module  ---&gt;  bnBENCH: bn_set_zero                      =    0.0024 usBENCH: bn_rand                          =    0.0864 usBENCH: bn_rand_security                 =    0.0656 usBENCH: bn_copy                          =    0.0063 usBENCH: bn_get_bits                      =    0.0017 usBENCH: bn_get_bit                       =    0.0021 usBENCH: bn_set_bit                       =    0.0065 usBENCH: bn_truncate                      =    0.0013 usBENCH: bn_truncate_bits                 =    0.0009 usBENCH: bn_add                           =    0.0085 usBENCH: bn_add_dig                       =    0.0056 usBENCH: bn_sub                           =    0.0096 usBENCH: bn_sub_dig                       =    0.0055 usBENCH: bn_mul                           =    0.0423 usBENCH: bn_sqr                           =    0.0420 usBENCH: bn_div                           =    0.0080 usBENCH: bn_mod                           =    0.1465 usBENCH: bn_cmp                           =    0.0014 usBENCH: bn_lsh                           =    0.0072 usBENCH: bn_rsh                           =    0.0029 usBENCH: bn_mod_add                       =    0.1829 usBENCH: bn_mod_sub                       =    0.1042 usBENCH: bn_mod_hlv                       =    0.0898 usBENCH: mont_compute_R                   =    0.1209 usBENCH: mod_inv                          =  139.5866 usBENCH: mod_inv_useNewton                =    1.7169 usBENCH: mont_compute_N_prime             =    2.4169 usBENCH: mont_ctx_init                    =   13.0413 usBENCH: bn_mod_rdc                       =    0.1674 usBENCH: bn_mod_mul                       =   14.3162 usBENCH: bn_mod_exp                       =  142.5800 us+------------------------------------------------------------------------------+
